// Bootstrap: wires renderer + game + HUD + settings, owns the frame loop,
// input handling, screen state, and the headless playtest API (window.GAME).

import { Renderer } from './renderer.js';
import { Game, WEAPONS } from './game.js';
import { AudioEngine } from './audio.js';
import { Settings, buildSettingsUI } from './settings.js';
import { HUD, buildBuyMenu } from './hud.js';
import { MATERIAL_NAMES } from './map.js';

const $ = id => document.getElementById(id);

const settings = new Settings();
const audio = new AudioEngine(settings);
const canvas = $('view');

let renderer;
try {
  renderer = new Renderer(canvas);
} catch (e) {
  $('fatal').textContent = e.message;
  $('fatal').style.display = 'flex';
  throw e;
}

let hud;
let screen = 'menu'; // menu | game | pause | settings(menuSettings) | buy overlays
let buyOpen = false;
let pointerLocked = false;
let lastT = performance.now();
let fpsAcc = 0, fpsN = 0, fpsShown = 0;
let frameAccum = 0;

const game = new Game(settings, audio, {
  onPhase(phase) {
    $('phase-banner').textContent = phase === 'buy' ? `ROUND ${game.round} — BUY PHASE` : 'GO GO GO';
    $('phase-banner').classList.add('show');
    setTimeout(() => $('phase-banner').classList.remove('show'), 1800);
    if (phase === 'buy') { buyOpen = true; syncOverlays(); }
    if (phase === 'live') { buyOpen = false; syncOverlays(); }
  },
  onRoundEnd(won, reason) {
    $('phase-banner').textContent = `${won ? 'ROUND WON' : 'ROUND LOST'} — ${reason}`;
    $('phase-banner').classList.add('show');
    setTimeout(() => $('phase-banner').classList.remove('show'), 2600);
  },
  onMatchEnd(won) {
    $('match-result').textContent = won ? 'VICTORY' : 'DEFEAT';
    $('match-stats').textContent =
      `${game.score.player} : ${game.score.bots} · ${game.kills} kills · ${game.deaths} deaths`;
    showScreen('matchend');
  },
  onKill(bot, head, weapon) {
    hud.addKillfeed(`YOU ${head ? '☠' : '⟶'} ${bot.name} [${WEAPONS[weapon].name}]`, head);
  },
  onDamage() {},
  onPlayerDamage(dmg, srcPos) { hud.onPlayerDamage(); },
  onShot(info) { hud.onShot(info, currentCam()); },
  onBotShot() {},
});

hud = new HUD(game, settings);

// ---------- camera ----------
function currentCam() {
  const basis = game.player ? game.camBasis() : {
    fwd: [Math.sin(menuYaw) * 0.985, -0.17, -Math.cos(menuYaw) * 0.985],
    right: [Math.cos(menuYaw), 0, Math.sin(menuYaw)],
    up: null,
  };
  if (!basis.up) {
    const f = basis.fwd, r = basis.right;
    basis.up = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
  }
  const gfx = settings.gfx();
  let fov = gfx.fov;
  if (game.player && game.player.scoped) fov *= 0.28;
  return {
    pos: game.player ? game.eyePos() : [Math.sin(menuYaw * 0.3) * 6, 9, 24],
    fwd: basis.fwd,
    right: basis.right,
    up: basis.up,
    fov,
  };
}

let menuYaw = 0;

// ---------- screens ----------
function showScreen(s) {
  screen = s;
  $('menu').style.display = s === 'menu' ? 'flex' : 'none';
  $('pause').style.display = s === 'pause' ? 'flex' : 'none';
  $('settings-screen').style.display = s === 'settings' ? 'flex' : 'none';
  $('matchend').style.display = s === 'matchend' ? 'flex' : 'none';
  $('hud').style.display = (s === 'game') ? 'block' : 'none';
  syncOverlays();
}

function syncOverlays() {
  $('buy-menu').style.display = (screen === 'game' && buyOpen) ? 'block' : 'none';
}

let settingsReturnTo = 'menu';
function openSettings(from) {
  settingsReturnTo = from;
  buildSettingsUI($('settings-panel'), settings, () => showScreen(settingsReturnTo));
  showScreen('settings');
}

function startGame() {
  audio.unlock();
  audio.startAmbient();
  game.startMatch();
  showScreen('game');
  requestPointerLock();
}

function requestPointerLock() {
  if (canvas.requestPointerLock) {
    const r = canvas.requestPointerLock();
    if (r && r.catch) r.catch(() => {}); // headless or denied: keyboard still works
  }
}

// ---------- input ----------
const KEYMAP = { KeyW: 'fwd+', KeyS: 'fwd-', KeyA: 'strafe-', KeyD: 'strafe+' };

document.addEventListener('keydown', e => {
  if (e.repeat) return;
  if (screen === 'game') {
    if (KEYMAP[e.code]) applyMove(e.code, true);
    else if (e.code === 'Space') game.input.jump = true;
    else if (e.code === 'ControlLeft') {
      game.input.crouch = settings.get('controls.crouchToggle') ? !game.input.crouch : true;
    }
    else if (e.code === 'ShiftLeft') game.input.walk = true;
    else if (e.code === 'KeyR') game.reload();
    else if (e.code === 'KeyB') { buyOpen = !buyOpen; syncOverlays(); }
    else if (e.code === 'Digit1') game.switchWeapon(0);
    else if (e.code === 'Digit2') game.switchWeapon(1);
    else if (e.code === 'Digit3') game.switchWeapon(2);
    else if (e.code === 'Escape') { showScreen('pause'); document.exitPointerLock?.(); }
  } else if (screen === 'pause' && e.code === 'Escape') {
    showScreen('game');
    requestPointerLock();
  }
});

document.addEventListener('keyup', e => {
  if (KEYMAP[e.code]) applyMove(e.code, false);
  else if (e.code === 'Space') game.input.jump = false;
  else if (e.code === 'ControlLeft' && !settings.get('controls.crouchToggle')) game.input.crouch = false;
  else if (e.code === 'ShiftLeft') game.input.walk = false;
});

function applyMove(code, down) {
  const m = KEYMAP[code];
  const axis = m.slice(0, -1);
  const dir = m.endsWith('+') ? 1 : -1;
  const cur = game.input[axis];
  if (down) game.input[axis] = dir;
  else if (cur === dir) game.input[axis] = 0;
}

canvas.addEventListener('mousedown', e => {
  if (screen !== 'game') return;
  if (!pointerLocked) requestPointerLock();
  if (e.button === 0) game.input.fire = true;
  if (e.button === 2) game.input.scope = !game.input.scope;
});
document.addEventListener('mouseup', e => {
  if (e.button === 0) game.input.fire = false;
});
canvas.addEventListener('contextmenu', e => e.preventDefault());

document.addEventListener('pointerlockchange', () => {
  pointerLocked = document.pointerLockElement === canvas;
  if (!pointerLocked && screen === 'game') showScreen('pause');
});

document.addEventListener('mousemove', e => {
  if (!pointerLocked || screen !== 'game' || !game.player) return;
  const sens = settings.get('controls.sensitivity') * 0.0022 *
    (game.player.scoped ? settings.get('controls.adsScale') : 1);
  const inv = settings.get('controls.invertY') ? -1 : 1;
  game.player.yaw += e.movementX * sens;
  game.player.pitch -= e.movementY * sens * inv;
  game.player.pitch = Math.max(-1.55, Math.min(1.55, game.player.pitch));
});

// menu buttons
$('btn-play').addEventListener('click', startGame);
$('btn-settings').addEventListener('click', () => openSettings('menu'));
$('btn-resume').addEventListener('click', () => { showScreen('game'); requestPointerLock(); });
$('btn-pause-settings').addEventListener('click', () => openSettings('pause'));
$('btn-quit').addEventListener('click', () => { game.state = 'menu'; showScreen('menu'); });
$('btn-again').addEventListener('click', startGame);
$('btn-menu').addEventListener('click', () => { game.state = 'menu'; showScreen('menu'); });

buildBuyMenu($('buy-menu'), game, item => game.buy(item));

settings.onChange(path => {
  audio.updateAmbient();
  if (path.startsWith('crosshair') || path === '*') hud.updateCrosshair();
});

// ---------- frame loop ----------
function frame(now) {
  const dtRaw = (now - lastT) / 1000;
  lastT = now;
  const dt = Math.min(dtRaw, 0.1);

  const gfx = settings.gfx();
  if (gfx.frameCap > 0) {
    frameAccum += dtRaw;
    if (frameAccum < 1 / gfx.frameCap) {
      requestAnimationFrame(frame);
      return;
    }
    frameAccum = 0;
  }

  if (screen === 'menu' || screen === 'matchend') menuYaw += dt * 0.1;
  if (screen === 'game') game.update(dt);

  renderer.resize(gfx.resolutionScale);
  renderer.setSpheres(game.player ? game.renderSpheres() : []);
  // muzzle flash light follows the player's gun
  if (game.player && hud.flashT > 0) {
    const eye = game.eyePos();
    const { fwd } = game.camBasis();
    renderer.setMuzzleLight(eye[0] + fwd[0] * 1.4, eye[1] + fwd[1] * 1.4 - 0.2, eye[2] + fwd[2] * 1.4, 18, [1, 0.75, 0.4]);
  } else {
    renderer.setMuzzleLight(0, -100, 0, 0);
  }
  renderer.render(currentCam(), now / 1000, gfx);

  if (screen === 'game') {
    hud.draw(dt, currentCam());
    hud.updateDOM();
    hud.updateCrosshair();
  }

  // fps counter
  fpsAcc += dtRaw; fpsN++;
  if (fpsAcc >= 0.5) {
    fpsShown = Math.round(fpsN / fpsAcc);
    fpsAcc = 0; fpsN = 0;
    const el = $('fps');
    el.style.display = gfx.showFps ? 'block' : 'none';
    el.textContent = `${fpsShown} FPS · RT ${canvas.width}×${canvas.height}`;
  }

  requestAnimationFrame(frame);
}

hud.updateCrosshair();
showScreen('menu');
requestAnimationFrame(frame);

// ---------- playtest API ----------
window.GAME = {
  ready: true,
  game, settings, audio, renderer,
  materialNames: MATERIAL_NAMES,
  test: {
    start() { startGame(); },
    skipBuy() { if (game.state === 'buy') game.goLive(); },
    state() {
      return {
        screen, gameState: game.state, round: game.round, money: game.money,
        kills: game.kills, score: { ...game.score },
        hp: game.player ? game.player.hp : null,
        pos: game.player ? [...game.player.pos] : null,
        botsAlive: game.bots.filter(b => b.alive).length,
        fps: fpsShown,
        canvas: { w: canvas.width, h: canvas.height },
        weapon: game.player ? game.player.current : null,
        ammo: game.player ? game.player.weapons[game.player.current].ammo : null,
      };
    },
    pose(x, y, z, yaw, pitch) {
      game.player.pos = [x, y, z];
      game.player.vel = [0, 0, 0];
      game.player.yaw = yaw;
      game.player.pitch = pitch;
    },
    aimAtBot(i) {
      const b = game.bots[i];
      const eye = game.eyePos();
      const h = b.headPos();
      const d = [h[0] - eye[0], h[1] - eye[1], h[2] - eye[2]];
      game.player.yaw = Math.atan2(d[0], -d[2]);
      game.player.pitch = Math.atan2(d[1], Math.hypot(d[0], d[2]));
    },
    fire() { game.tryFire(); },
    damageBot(i, dmg, head = false) { game.damageBot(game.bots[i], dmg, head, 'rifle'); },
    buy(item) { return game.buy(item); },
    setSetting(path, val) { settings.set(path, val); },
    getSetting(path) { return settings.get(path); },
    sfxReport() { return audio.report(); },
    materialView(id) { renderer.debugMat = id; },
    botInfo() {
      return game.bots.map(b => ({
        name: b.name, alive: b.alive, hp: b.hp, state: b.state,
        pos: [+b.pos[0].toFixed(1), +b.pos[1].toFixed(1), +b.pos[2].toFixed(1)],
      }));
    },
    step(dt) { game.update(dt); },
  },
};
